async function mountMedia(){for(const el of document.querySelectorAll('[data-media]')){const t=el.dataset.media,id=el.dataset.id;try{
 if(t==='svg'){const [svg,meta]=await Promise.all([fetch(`figures/${id}.svg`).then(r=>{if(!r.ok)throw 0;return r.text();}),fetch(`figures/${id}.json`).then(r=>r.ok?r.json():{}).catch(()=>({}))]);
  el.innerHTML=`<div class="media-svg">${svg.replace(/<\?xml[^>]*>/,'')}</div><figcaption>${meta.title?`<strong>${esc(meta.title)}.</strong> `:''}${esc(meta.caption||'')}</figcaption>${meta.alt?`<details><summary>Текстовая версия схемы</summary><p class="alt">${esc(meta.alt)}</p></details>`:''}`;}
 else if(t==='widget'){const m=await import(`./widgets/${id}.js`);state.widgets=state.widgets||{};el.innerHTML='<div class="widget-host"></div>';m.mount(el.firstChild,{state:state.widgets,save});}
 else if(t==='video'){const tr=await fetch(`media/${id}.txt`).then(r=>r.ok?r.text():'').catch(()=>'');const head=await fetch(`media/${id}.mp4`,{method:'HEAD'});if(!head.ok)throw 0;
  el.innerHTML=`<video controls preload="metadata" playsinline poster="media/${id}.jpg"><source src="media/${id}.mp4" type="video/mp4"><track kind="captions" srclang="ru" label="Русские субтитры" src="media/${id}.vtt"></video><figcaption><strong>Видео: ${esc(el.dataset.title)}.</strong> Текст и субтитры встроены в видео — смотреть можно без звука.</figcaption>${tr?`<details><summary>Расшифровка</summary><p class="alt">${esc(tr)}</p></details>`:''}`;}
}catch{el.remove();}}}
const DOCX_URL='vendor/docx.iife.js';
function loadDocx(){if(window.docx)return Promise.resolve(window.docx);return new Promise((res,rej)=>{const s=document.createElement('script');s.src=DOCX_URL;s.onload=()=>res(window.docx);s.onerror=rej;document.head.append(s);});}
function surname(){const f=(state.profile.student||'').trim().split(/\s+/)[0];return f?'_'+f.replace(/[^\p{L}\p{N}-]/gu,''):'';}
async function exportDocx(kind,arg){notice('Готовлю документ Word…');try{const D=await loadDocx();const {buildGostDoc}=await import('./docx-gost.js');const pr=state.profile;let opt,name;
 const txt=v=>(v||'').trim()?v:'Не заполнено.';
 if(kind==='strategy'){opt={workType:'Маркетинговая стратегия',topic:pr.topic?`«${pr.topic}»`:'',blocks:projectFields.map(([id,title],i)=>[{section:title.replace(/^(\d+)\.\s*/,'$1 '),pageBreak:i===0},{text:txt(state.project[id])}]).flat().concat([{structural:'Список использованных источников'},{hint:'[Оформите источники по ГОСТ Р 7.0.100-2018.]'}],appendixBlocks())};name='Стратегия';}
 else if(kind==='kt'){const k=capstone.checkpoints.find(x=>x.id===arg);opt={workType:`Отчёт по контрольной точке ${k.code}`,topic:`«${k.title}»${pr.topic?' — '+pr.topic:''}`,blocks:[{structural:'Введение',pageBreak:true},{text:k.goal+(capstone.tracks[state.capstone.track]?` Траектория: ${capstone.tracks[state.capstone.track].title}.`:'')},...k.fields.map(([f,title],i)=>[{section:`${i+1} ${title}`,pageBreak:false},{text:txt(state.capstone.fields[ktKey(k,f)])}]).flat(),{section:`${k.fields.length+1} Проверка готовности`,pageBreak:false},{list:k.check.map((c,j)=>(state.capstone.checks[k.id+'_'+j]?'выполнено: ':'не выполнено: ')+c)}]};name=k.code;}
 else if(kind==='capstone'){opt={workType:'Отчёт по сквозному проекту',topic:pr.topic?`«${pr.topic}»`:'',blocks:capstone.checkpoints.map((k,ki)=>[{section:`${k.code.replace('КТ-','')} ${k.title}`,pageBreak:ki===0},...k.fields.map(([f,title],i)=>[{section:`${k.code.replace('КТ-','')}.${i+1} ${title}`,level:2},{text:txt(state.capstone.fields[ktKey(k,f)])}]).flat()]).flat().concat(projectFields.some(([id])=>(state.project[id]||'').trim())?[{section:'Итоговая стратегия',pageBreak:true},...projectFields.map(([id,title])=>[{section:title.replace(/^(\d+)\.\s*/,'$1 '),level:2},{text:txt(state.project[id])}]).flat()]:[],appendixBlocks())};name='Сквозной_проект';}
 else {opt={workType:'Рабочие записки по урокам',blocks:course.modules.map((m,mi)=>[{section:`${mi+1} ${m.title}`,pageBreak:mi===0},...m.lessons.map((l,li)=>[{section:`${mi+1}.${li+1} ${l.title}`,level:2},{text:txt(state.answers[l.id])}]).flat()]).flat()};name='Записки_по_урокам';}
 const doc=buildGostDoc(D,{...opt,student:pr.student,group:pr.group,supervisor:pr.supervisor});const blob=await D.Packer.toBlob(doc);
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${name}${surname()}.docx`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);notice('Документ Word скачан.');
}catch(e){console.error(e);notice('Не удалось собрать документ Word. Проверьте подключение к интернету и повторите.');}}
function profileHTML(){const p=state.profile;return `<details class="profile"${p.student?'':' open'}><summary>Данные для титульного листа${p.student?': '+esc(p.student):''}</summary><p class="small">Нужны для документов Word по ГОСТ 7.32. Хранятся только в этом браузере.</p><div class="profile-grid">${[['student','Ф. И. О.','Иванова Анна Сергеевна'],['group','Группа',''],['supervisor','Преподаватель','должность, Ф. И. О.'],['topic','Объект или тема работы','например: база отдыха в дельте Волги']].map(([k,l,ph])=>`<label>${l}<input data-profile="${k}" value="${esc(p[k]||'')}" placeholder="${esc(ph)}" maxlength="200"></label>`).join('')}</div></details>`;}
