function filesHTML(){return FILES.map(([h,list])=>`<h3>${h}</h3><ul class="files">${list.map(([f,l,t])=>`<li><a href="${f}" download><span class="fmt">${t}</span>${esc(l)}</a></li>`).join('')}</ul>`).join('');}
function ktTemplatesHTML(k){return k.templates?`<section><h2>Шаблоны и памятки</h2><ul class="files">${k.templates.map(([f,l])=>`<li><a href="${f}" download><span class="fmt">${f.split('.').pop().toUpperCase()}</span>${esc(l)}</a></li>`).join('')}</ul></section>`:'';}
const ktKey=(k,f)=>k.id+'_'+f;
function ktFilled(k){return k.fields.filter(([f])=>(state.capstone.fields[ktKey(k,f)]||'').trim()).length;}
function ktChecked(k){return k.check.filter((_,i)=>state.capstone.checks[k.id+'_'+i]).length;}
function ktComplete(k){return ktFilled(k)===k.fields.length&&ktChecked(k)===k.check.length;}
function ktDone(){return capstone.checkpoints.filter(ktComplete).length;}
function capstoneHTML(){const c=capstone,t=state.capstone.track;return `<div class="eyebrow">САМОСТОЯТЕЛЬНАЯ РАБОТА · ${c.hoursTotal} Ч</div><h1>${esc(c.title)}</h1><p class="lead">${esc(c.lead)}</p><div class="stats">${c.checkpoints.map(k=>`<div><strong>${k.hours}</strong><span>${k.code} · ч</span></div>`).join('')}</div><p class="small">${esc(c.hoursNote)}</p><h2>Почему так</h2><div class="cards">${c.principles.map(([h,p])=>`<article class="card"><h3>${esc(h)}</h3><p>${esc(p)}</p></article>`).join('')}</div><h2>Выберите траекторию</h2><div class="cards">${Object.entries(c.tracks).map(([id,tr])=>`<article class="card${t===id?' selected':''}"><h3>${esc(tr.title)}</h3><p>${esc(tr.text)}</p><ul>${tr.admission.map(a=>`<li>${esc(a)}</li>`).join('')}</ul><button class="${t===id?'':'secondary'}" data-track="${id}">${t===id?'Выбрано ✓':'Выбрать'}</button></article>`).join('')}</div><h2>Объекты для траектории Б</h2>${c.cases.map(x=>`<details><summary>${esc(x.name)}</summary><p><strong>Стратегический вопрос.</strong> ${esc(x.question)}</p><p><strong>Что можно собрать самостоятельно.</strong> ${esc(x.data)}</p></details>`).join('')}<p class="small">Перед сбором данных проверьте на официальном сайте объекта действующие правила посещения и цены: они меняются.</p><h2>Контрольные точки</h2><div class="table-wrap"><table><thead><tr><th>Точка</th><th>Результат</th><th>Часы</th><th>Связь с уроками</th><th>Статус</th></tr></thead><tbody>${c.checkpoints.map(k=>`<tr><th><a href="#${k.id}">${k.code} · ${esc(k.title)}</a></th><td>${esc(k.goal)}</td><td>${k.hours}</td><td>${esc(k.links)}</td><td>${ktComplete(k)?'Готово ✓':`${ktFilled(k)}/${k.fields.length} полей · ${ktChecked(k)}/${k.check.length} проверок`}</td></tr>`).join('')}</tbody></table></div><h2>Что и куда сдаётся</h2><div class="table-wrap"><table><thead><tr><th>Точка</th><th>Что сдаётся</th><th>Формат</th><th>Срок</th></tr></thead><tbody>${c.submission.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="small">${esc(c.submissionNote)}</p>${profileHTML()}<h2>Календарь для заочной формы</h2><div class="table-wrap"><table><tbody>${c.schedule.map(([w,d])=>`<tr><th>${esc(w)}</th><td>${esc(d)}</td></tr>`).join('')}</tbody></table></div><h2>Оценивание</h2><p>${esc(c.grading)}</p><div class="actions"><a class="button" href="#${c.checkpoints.find(k=>!ktComplete(k))?.id||'project'}">${ktDone()?'Продолжить проект':'Начать с КТ-0'} →</a><button class="secondary" id="export-capstone">Весь проект в Word</button></div><h2>Шаблоны и памятки</h2>${filesHTML()}`;}
function ktHTML(k){const i=capstone.checkpoints.indexOf(k),prev=capstone.checkpoints[i-1],next=capstone.checkpoints[i+1],tr=capstone.tracks[state.capstone.track];return `<article class="lesson"><div class="eyebrow">СКВОЗНОЙ ПРОЕКТ · ${k.code} · ${k.hours} Ч</div><h1>${esc(k.title)}</h1><p class="lead">${esc(k.goal)}</p><p class="small">${esc(k.links)}${tr?' · '+esc(tr.title):' · <a href="#capstone">выберите траекторию</a>'}</p><section><h2>Что сделать</h2><ol>${k.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${k.tip?`<div class="callout">${esc(k.tip)}</div>`:''}</section>${k.example?`<details class="example"><summary>Пример выполнения</summary><p>${esc(k.example)}</p></details>`:''}${mediaSlots(k.id)}${ktTemplatesHTML(k)}<section><h2>Как выполнить</h2><div class="cards"><article class="card"><h3>В аудитории</h3><p>${esc(k.modes.class)}</p></article><article class="card"><h3>Самостоятельно</h3><p>${esc(k.modes.self)}</p></article></div></section>${k.fields.map(([f,title,ph])=>`<section class="task project-field"><span class="tag">АРТЕФАКТ</span><h2>${esc(title)}</h2><label for="kt-${ktKey(k,f)}">${esc(ph)}</label><textarea id="kt-${ktKey(k,f)}" data-kt="${ktKey(k,f)}" maxlength="30000">${esc(state.capstone.fields[ktKey(k,f)]||'')}</textarea></section>`).join('')}<section class="task"><h2>Готово к сдаче?</h2>${k.check.map((c,j)=>`<label class="option"><input type="checkbox" data-check="${k.id}_${j}" ${state.capstone.checks[k.id+'_'+j]?'checked':''}><span>${esc(c)}</span></label>`).join('')}<p class="small" id="kt-status" role="status">${ktComplete(k)?'Контрольная точка готова к сдаче ✓':'Заполните поля и отметьте проверки.'}</p></section><section><h2>Критерии оценки</h2><ul>${k.criteria.map(c=>`<li>${esc(c)} — 0 / 1 / 2</li>`).join('')}</ul></section><div class="actions">${prev?`<a class="button secondary" href="#${prev.id}">← ${prev.code}</a>`:'<a class="button secondary" href="#capstone">← Обзор проекта</a>'}<a class="button" href="#${next?next.id:'project'}">${next?next.code+' →':'К разделу «Моя стратегия» →'}</a></div>${profileHTML()}<div class="actions">${k.id==='kt6'?'<button id="export-strategy-kt">Итоговая стратегия с приложениями А и Б (Word)</button>':''}<button ${k.id==='kt6'?'class="secondary" ':''}id="export-kt">Скачать ${k.code} в Word</button><button class="secondary" id="export-capstone-kt">Весь проект в Word</button></div>${k.id==='kt6'?'<p class="small">Сдаётся итоговая стратегия с приложениями — первая кнопка. Файл «КТ-6» содержит только план защиты, рецензии и отзыв.</p>':''}<p class="small">Документ собирается с титульным листом по ГОСТ 7.32. Ответы хранятся только в этом браузере — скачивайте документ после каждой контрольной точки.</p></article>`;}
function guideHTML(){const g=guide,list=x=>`<ul>${x.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`,table=x=>`<div class="table-wrap"><table><tbody>${x.map(([a,b])=>`<tr><th>${esc(a)}</th><td>${esc(b)}</td></tr>`).join('')}</tbody></table></div>`;return `<div class="eyebrow">РУКОВОДСТВО</div><h1>${esc(g.title)}</h1><p class="lead">${esc(g.lead)}</p><div class="cards"><article class="card"><h3>Самостоятельно</h3>${list(g.self)}</article><article class="card"><h3>В аудитории</h3>${list(g.classroom)}</article></div><h2>Часы рабочей программы</h2>${table(g.hours)}<h2>Занятие по экономике: 150 минут в аудитории или самопроверка дома</h2>${table(g.economics)}<p class="small">Это же занятие можно пройти самостоятельно: уроки модуля 2 о бронированиях и сезонности, тренажёр, затем уроки модуля 3 о порогах и переговорах.</p><h2>Литература к курсу</h2>${table(g.literature)}<div class="actions"><a class="button" href="#capstone">К сквозному проекту →</a><a class="button secondary" href="#m1l1">К первому уроку →</a></div>`;}
