const appendixFields=[['ailog','Приложение А. Журнал использования ИИ','Одна строка — одно обращение к ИИ, результат которого попал в КТ или в записку (самопроверку по урокам не записывайте). Колонки через «|», «;» или табуляцию; можно вставить таблицу прямо из ИИ или Excel: Дата | Сервис | Задача | Что попросил | Что взял | Что отверг и почему. Если ИИ не использовался, напишите: «ИИ не использовался».',['Дата','Сервис','Задача','Что попросил','Что взял','Что отверг и почему']],['claims','Приложение Б. Таблица утверждений','Одна строка — одно утверждение, колонки через «|», «;» или табуляцию; можно вставить таблицу прямо из ИИ или Excel: № | Утверждение | Откуда | Страница или фрагмент | Статус (проверено — то, что в уроках называется фактом; расчёт; оценка; допущение). Обычно 10–25 строк.',['№','Утверждение','Откуда','Страница или фрагмент','Статус']]];
function parseRows(v,header){const lines=(v||'').split('\n').map(x=>x.trim()).filter(Boolean),rows=[],rest=[],warn=[];const sep=l=>l.includes('|')?'|':l.includes('\t')?'\t':l.includes(';')?';':null;lines.forEach((l,n)=>{const d=sep(l);if(!d){rest.push(l);return;}let c=l.split(d).map(y=>y.trim());if(d==='|'){if(c[0]==='')c.shift();if(c[c.length-1]==='')c.pop();}if(c.every(x=>/^[-:\s]*$/.test(x)))return;if(c.map(x=>x.toLowerCase()).join('|')===header.map(x=>x.toLowerCase()).join('|')||c[0].toLowerCase()===header[0].toLowerCase()&&(c[1]||'').toLowerCase()===header[1].toLowerCase())return;if(c.length>header.length){warn.push(`строка ${n+1}: колонок ${c.length} вместо ${header.length} — лишние добавлены в последнюю`);c=[...c.slice(0,header.length-1),c.slice(header.length-1).join('; ')];}while(c.length<header.length)c.push('');rows.push(c);});return {rows,rest:rest.join('\n'),warn};}
function appendixBlocks(){return appendixFields.flatMap(([id,title,,header])=>{const {rows,rest}=parseRows(state.project[id],header);return [{structural:title},...(rows.length?[{table:title.replace(/^Приложение .\.\s*/,''),header,rows}]:[]),...(rest||!rows.length?[{text:rest||'Не заполнено.'}]:[])];});}
function appendixStatus(id){const f=appendixFields.find(x=>x[0]===id);if(!f)return '';const {rows,rest,warn}=parseRows(state.project[id],f[3]);return (state.project[id]||'').trim()?`Распознано строк таблицы: ${rows.length}${rest?' · текст вне таблицы тоже попадёт в приложение':''}${warn.length?' · '+warn.join('; '):''}`:'Пока пусто.';}
const projectFields=[['problem','1. Проблема и критерий успеха','Какое решение принимается? Каковы горизонт, ограничения и единица анализа?'],['segment','2. Целевой сегмент','Какая потребность объединяет клиентов? Какие свидетельства поддерживают выбор?'],['offer','3. Предложение и позиционирование','Что обещаем клиенту и чем обеспечиваем выполнение?'],['economics','4. Экономика стратегии','Сравните каналы, цены, отмены, затраты и вытеснение. Укажите вычисления.'],['uncertainty','5. Неопределённость и альтернатива','Какое допущение наиболее уязвимо? Где порог смены решения?'],['promotion','6. Программа продвижения','Сегмент и сообщение, каналы с задачей, бюджетом и показателем результата, правовые требования.'],['experiment','7. Проверка','Сравнение, метрика, срок, дополнительность и правило остановки.'],['revision','8. Пересмотр решения и пределы вывода','Что изменилось после новых данных? Что эти данные не позволяют утверждать?']];
function projectHTML(){return `<div class="eyebrow">ИТОГОВАЯ РАБОТА</div><h1>Ваша стратегия</h1><p class="lead">Соедините решения в обоснованную записку для объекта из сквозного проекта. Если вы проходите только уроки, пишите её для «Маяка». Нужны расчёты, альтернатива и условия пересмотра.</p><div class="callout">Рекомендуемый объём — до четырёх страниц и отдельная расчётная таблица. Самооценка помогает подготовиться к защите; итоговую оценку выставляет преподаватель.</div>${projectFields.map(([id,title,prompt])=>`<section class="project-field"><h2>${title}</h2><label for="project-${id}">${prompt}</label><textarea id="project-${id}" data-project="${id}" maxlength="30000">${esc(state.project[id]||'')}</textarea></section>`).join('')}<h2>Приложения — условие допуска к защите</h2><p>Журнал использования ИИ и таблица утверждений обязательны для всех, даже если вы не пользовались ИИ: без них работа не допускается к защите. Приложение А занимает 10–20 минут, приложение Б (10–25 строк) — 1,5–2 часа; это входит в 8 часов КТ-6. Порядок работы с ИИ в восемь шагов — на странице <a href="#ai-pipeline">«ИИ в работе»</a>.</p>${appendixFields.map(([id,title,prompt])=>`<section class="project-field"><h2>${title}</h2><label for="project-${id}">${prompt}</label><textarea id="project-${id}" data-project="${id}" maxlength="30000" rows="12">${esc(state.project[id]||'')}</textarea><p class="small" id="status-${id}" role="status">${esc(appendixStatus(id))}</p></section>`).join('')}<details class="example"><summary>Примеры строк приложений А и Б</summary>${tableHTML(aiGuide.pipeline.log.header,aiGuide.pipeline.log.example)}${tableHTML(aiGuide.pipeline.claims.header,aiGuide.pipeline.claims.example)}<p class="small">${esc(aiGuide.pipeline.claims.hint)}</p></details><h2>Рубрика оценки</h2>${rubricHTML()}${profileHTML()}<div class="actions"><button id="export-project">Скачать стратегию в Word</button><button class="secondary" id="print-project">Печатать / сохранить PDF</button></div><p class="small">Нужен свой формат? Возьмите <a href="templates/KT-6_Marketingovaya-strategiya.docx" download>шаблон итоговой стратегии (Word, ГОСТ 7.32)</a>.</p>`;}
function rubricHTML(){return `<div class="table-wrap"><table><thead><tr><th>Критерий</th><th>Компетенция</th><th>0 · Слабый</th><th>1 · Достаточный</th><th>2 · Сильный</th></tr></thead><tbody>${course.rubric.map(r=>`<tr><th>${esc(r.criterion)}</th><td>${esc(r.competence)}</td><td>${esc(r.weak)}</td><td>${esc(r.adequate)}</td><td>${esc(r.strong)}</td></tr>`).join('')}</tbody></table></div><p class="small">Максимум 14 баллов. Ориентир для зачёта с оценкой: 12–14 — «отлично», 9–11 — «хорошо», 7–8 — «удовлетворительно»; нулевая оценка за данные или экономику требует доработки. Балл 2 соответствует третьему уровню сформированности компетенции по рабочей программе, балл 1 — второму.</p>`;}
function resourcesHTML(){return `<div class="eyebrow">МАТЕРИАЛЫ И РЕЗЕРВНАЯ КОПИЯ</div><h1>Всё для работы</h1><div class="resource-links"><a href="#guide">Как работать с курсом: в аудитории и самостоятельно →</a></div><h2>Шаблоны, таблицы и памятки</h2>${filesHTML()}<h2>Ваши ответы</h2>${profileHTML()}<p>Ответы хранятся только в браузере на этом устройстве. Сайт сам ничего не отправляет: чтобы сдать работу, скачайте документ Word и отправьте файл преподавателю в мессенджер; контакт преподаватель даёт на первом занятии.</p><div class="actions"><button id="export-capstone">Сквозной проект в Word</button><button class="secondary" id="export-notes">Записки по урокам в Word</button><button class="secondary" id="export-all">Резервная копия ответов (.json)</button></div><p class="small">Резервная копия нужна, чтобы перенести ответы на другое устройство или восстановить их после очистки браузера; преподавателю её отправлять не нужно.</p><label for="import-file">Восстановить ответы из резервной копии (.json)</label><input id="import-file" type="file" accept=".json,application/json"><p class="small">Импорт заменит ответы в этом браузере после подтверждения.</p><button class="secondary" id="reset">Удалить локальный прогресс</button><h2>Словарь</h2>${course.glossary.map(g=>`<details><summary>${esc(g.term)}</summary><p>${esc(g.definition)}</p></details>`).join('')}`;}
function labHTML(){return `<div class="eyebrow">ТРЕНАЖЁР</div><h1>Загрузка ≠ результат</h1><p class="lead">Выберите канал сначала без календаря, затем проверьте решение по датам.</p><div class="callout">40 номеров × 30 дней = 1 200 номеро-ночей. Базовый спрос — 840 ночей. Дополнительные пакеты неделимы; подтверждённые бронирования сохраняются.</div><div class="table-wrap"><table><thead><tr><th>Параметр</th>${packages.map(p=>`<th>${p.name}</th>`).join('')}</tr></thead><tbody>${[['Брони, номеро-ночи','booked'],['Доля отмен','cancel'],['Цена состоявшейся ночи, ₽','price'],['Комиссия, доля выручки','commission'],['Обработка состоявшейся ночи, ₽','fee'],['Привлечение забронированной ночи, ₽','cac'],['Фиксированные расходы, ₽','fixed'],['Обслуживание состоявшейся ночи, ₽','variable']].map(([label,k])=>`<tr><th>${label}</th>${packages.map(p=>`<td>${num(p[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><section class="task"><h2>1. Зафиксируйте первоначальное решение</h2><label for="initial-channel">Предпочтительный пакет</label><select id="initial-channel">${packages.map(p=>`<option value="${p.id}">${p.name}</option>`).join('')}</select><label for="initial-reason">Ваш расчёт, допущение и запрос недостающих данных</label><textarea id="initial-reason">${esc(state.lab.reason||'')}</textarea><button id="reveal">${state.lab.revealed?'Календарь уже открыт':'Сохранить решение и открыть календарь'}</button><p class="small">Первое решение сохраняется отдельно от пересмотра.</p></section><section id="calendar" ${state.lab.revealed?'':'hidden'}><h2>2. Проверьте календарь</h2><div class="table-wrap"><table><thead><tr><th>Показатель</th><th>10 пиковых дней</th><th>20 остальных</th></tr></thead><tbody><tr><th>Мощность</th><td>400</td><td>800</td></tr><tr><th>Базовый спрос</th><td>370</td><td>470</td></tr>${packages.map(p=>`<tr><th>${p.name}</th><td>${p.peak}</td><td>${p.offpeak}</td></tr>`).join('')}</tbody></table></div><div class="controls"><label for="margin">Маржинальный доход вытесненной пиковой ночи: <strong id="margin-value"></strong><input id="margin" type="range" min="0" max="7000" step="10" value="${Number.isFinite(state.lab.margin)?state.lab.margin:5060}"></label><label for="base-peak">Базовый спрос в пиковые дни: <strong id="base-value"></strong><input id="base-peak" type="range" min="200" max="400" step="1" value="${Number.isFinite(state.lab.basePeak)?state.lab.basePeak:370}"></label><button class="secondary" id="reset-lab">Вернуть исходный сценарий</button></div><p class="small">Цена базовой ночи 7 000 ₽ × 0,98 − 1 800 ₽ = 5 060 ₽. Ползунки меняют допущения, а не прогнозируют рынок. Непиковый спрос фиксирован: вытеснения вне пика нет.</p><div id="lab-results" aria-live="polite"></div><div class="callout">При базовом спросе 370: корпоративный пакет предпочтителен при m &lt; 1 733,33 ₽; агрегатор — между 1 733,33 и 1 872 ₽; прямой — при m &gt; 1 872 ₽. При изменении спроса пороги нужно пересчитать.</div><label for="revision">3. Ваш пересмотр: что изменилось и почему?</label><textarea id="revision">${esc(state.lab.revision||'')}</textarea></section>`;}
function updateLab(){const margin=Number($('#margin').value),basePeak=Number($('#base-peak').value);$('#margin-value').textContent=money(margin);$('#base-value').textContent=basePeak+' ночей';const rows=packages.map(p=>({...p,...calculate(p,{calendar:true,margin,basePeak})})),best=bestPackage({calendar:true,margin,basePeak});const max=Math.max(...rows.map(p=>Math.abs(p.net)),1);setTimeout(()=>import('./widgets/capacity-band.js').then(m=>{const el=$('#lab-band');if(el)m.render(el,{basePeak,pkg:best.id,margin});}).catch(()=>{}),0);$('#lab-results').innerHTML=`<h2>Предпочтительный пакет: ${best.name}</h2><p class="metric">${money(best.net)}</p><p class="small">Изменение ожидаемого маржинального результата, не прибыль отеля.</p><div class="table-wrap"><table><thead><tr><th>Пакет</th><th>После отмен</th><th>До вытеснения</th><th>Вытеснено ночей</th><th>Результат</th></tr></thead><tbody>${rows.map(p=>`<tr><th>${p.name}</th><td>${p.nights}</td><td>${money(p.before)}</td><td>${p.displaced}</td><td>${money(p.net)}</td></tr>`).join('')}</tbody></table></div><div class="bars">${rows.map(p=>`<div><span>${p.name} · ${money(p.net)}</span><div class="bar-track"><div class="bar-fill ${p.net<0?'bar-negative':''}" style="width:${Math.abs(p.net)/max*100}%"></div></div></div>`).join('')}</div><div id="lab-band"></div><p class="small">Шкала показывает абсолютную величину результата; отрицательные значения отмечены оранжевым и знаком минус.</p>`;}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindResources(){$('#export-all').onclick=()=>download('rezervnaya-kopiya-otvetov.json',JSON.stringify({version:1,...state},null,2),'application/json');$('#export-notes').onclick=()=>exportDocx('lessons');$('#export-capstone').onclick=()=>exportDocx('capstone');bindProfile();$('#reset').onclick=()=>{if(confirm('Удалить ответы и прогресс в этом браузере? Сначала можно скачать резервную копию.')){state=emptyState();save();render();}};$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2000000){notice('Файл слишком большой: максимум 2 МБ.');return;}try{const data=JSON.parse(await file.text());if(data.version!==1)throw Error('version');const clean=validProgress(data,ids);if(!clean)throw Error('format');if(confirm('Заменить текущие ответы данными из файла?')){state=clean;save();render();notice('Ответы восстановлены.');}}catch{notice('Не удалось прочитать файл: нужна резервная копия (.json), скачанная на этом сайте.');}};}
function bindLab(){$('#initial-reason').oninput=e=>{if(!state.lab.revealed){state.lab.reason=e.target.value;save();}};$('#initial-channel').onchange=e=>{if(!state.lab.revealed){state.lab.initial=e.target.value;save();}};$('#initial-channel').value=packages.some(p=>p.id===state.lab.initial)?state.lab.initial:'corporate';if(state.lab.revealed){$('#initial-channel').disabled=true;$('#initial-reason').readOnly=true;}$('#reveal').onclick=()=>{if(!state.lab.revealed){if(!$('#initial-reason').value.trim()){notice('Сначала запишите обоснование выбора.');return;}state.lab={...state.lab,initial:$('#initial-channel').value,reason:$('#initial-reason').value,revealed:true};save();$('#calendar').hidden=false;$('#initial-channel').disabled=true;$('#initial-reason').readOnly=true;$('#reveal').textContent='Календарь открыт';}updateLab();};$('#margin').oninput=$('#base-peak').oninput=()=>{state.lab.margin=Number($('#margin').value);state.lab.basePeak=Number($('#base-peak').value);save();updateLab();};$('#reset-lab').onclick=()=>{$('#margin').value=5060;$('#base-peak').value=370;state.lab.margin=5060;state.lab.basePeak=370;save();updateLab();};$('#revision').oninput=e=>{state.lab.revision=e.target.value;save();};updateLab();}
function render(){sidebar();const raw=location.hash.slice(1)||'home',sub=/^ai-/.test(raw)?raw:'',route=sub?'ai':raw,l=lessons.find(l=>l.id===route),kt=capstone.checkpoints.find(k=>k.id===route);$('#main').innerHTML=l?lessonHTML(l):kt?ktHTML(kt):route==='capstone'?capstoneHTML():route==='guide'?guideHTML():route==='lab'?labHTML():route==='project'?projectHTML():route==='resources'?resourcesHTML():route==='ai'?aiHTML():home();if(l)bindLesson(l);if(l||route==='ai')bindCopy(l);if(sub)setTimeout(()=>document.getElementById(sub)?.scrollIntoView(),0);if(kt)bindKT(kt);mountMedia();document.querySelectorAll('.table-wrap').forEach(w=>{w.tabIndex=0;w.setAttribute('role','region');w.setAttribute('aria-label','Таблица, прокручивается по горизонтали');});document.body.classList.remove('toc-open');$('#toc-toggle')?.setAttribute('aria-expanded','false');const pp=$('#printable-project');if(pp)pp.remove();if(route==='capstone')bindCapstone();if(route==='lab')bindLab();if(route==='resources')bindResources();if(route==='project'){document.querySelectorAll('[data-project]').forEach(el=>el.oninput=()=>{state.project[el.dataset.project]=el.value;save();const st=$('#status-'+el.dataset.project);if(st)st.textContent=appendixStatus(el.dataset.project);});$('#export-project').onclick=()=>exportDocx('strategy');bindProfile();$('#print-project').onclick=printProject;}document.title=(l?l.title:kt?kt.code+' · '+kt.title:route==='capstone'?'Сквозной проект':route==='guide'?'Как работать с курсом':route==='lab'?'Тренажёр':route==='project'?'Моя стратегия':route==='resources'?'Материалы':route==='ai'?'ИИ в работе':'Маркетинговые стратегии в туризме')+' · курс';}
function printProject(){const old=$('#printable-project');if(old)old.remove();const section=document.createElement('section');section.id='printable-project';section.innerHTML='<h1>Моя стратегия</h1>'+[...projectFields,...appendixFields].map(([id,title])=>'<h2>'+esc(title)+'</h2><p>'+esc(state.project[id]||'Не заполнено.')+'</p>').join('');document.body.append(section);window.print();}
addEventListener('beforeprint',()=>{document.querySelectorAll('main textarea').forEach(t=>{const d=document.createElement('div');d.className='print-copy';d.textContent=t.value||'—';t.after(d);});});
addEventListener('afterprint',()=>{document.querySelectorAll('.print-copy').forEach(d=>d.remove());const pp=$('#printable-project');if(pp)pp.remove();});
$('#toc-toggle')?.addEventListener('click',()=>{const o=document.body.classList.toggle('toc-open');$('#toc-toggle').setAttribute('aria-expanded',o);});
$('#sidebar').addEventListener('click',e=>{if(e.target.closest('a')){document.body.classList.remove('toc-open');$('#toc-toggle')?.setAttribute('aria-expanded','false');}});
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();});
addEventListener('beforeprint',()=>document.querySelectorAll('details.case-more').forEach(d=>d.open=true));addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});render();
